def update_gist(content):
    url = f"https://api.github.com/gists/{GIST_ID}"
    headers = {"Authorization": f"token {GITHUB_TOKEN}"}
    data = {"files": {"vless_links.txt": {"content": content}}}
    response = requests.patch(url, headers=headers, json=data)
    if response.status_code == 200:
        print("Gist успешно обновлен!")
    else:
        print(f"Ошибка при обновлении: {response.status_code} - {response.text}")

def get_vless_links(target):
    url = target["url"]
    magic_key_str = target["key"]
    prefix = target["prefix"]

    try:
        response = requests.get(url, timeout=30).json()
        raw_bytes = base64.b64decode(response["data"])
        iv, ciphertext = raw_bytes[:16], raw_bytes[16:]
        key = hashlib.sha256(magic_key_str.encode('utf-8')).digest()

        process = subprocess.Popen(
            ['openssl', 'enc', '-d', '-aes-256-ctr', '-K', key.hex(), '-iv', iv.hex()],
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE
        )
        decrypted_bytes, err = process.communicate(input=ciphertext)

        if process.returncode != 0:
            return []

        with gzip.GzipFile(fileobj=io.BytesIO(decrypted_bytes)) as f:
            data = json.loads(f.read().decode('utf-8'))

        links = []
        configs = data.get("configs", {}).get("normal", [])

        for item in configs:
            config = item.get("config")
            if not config:
                continue

            # 1. ОБРАБОТКА ГОТОВОЙ ССЫЛКИ
            if isinstance(config, str):
                config = config.strip()
                # Извлекаем UUID и параметры, если это VLESS
                match = re.match(r"vless://([^@]+)@([^:]+):(\d+)\?(.*)#(.*)", config)
                if match:
                    uuid, _, port, query_str, remark = match.groups()
                    links.append(f"vless://{uuid}@8.6.112.0:{port}?{query_str}#{prefix}-{remark}")
                    continue
                elif "://" in config:
                    links.append(config)
                    continue

            # 2. JSON-конфиг
            try:
                conf = json.loads(config) if isinstance(config, str) else config
                proxy = next((o for o in conf.get("outbounds", []) if o.get("tag") == "proxy"), None)
                if not proxy: continue

                vnext = proxy["settings"]["vnext"][0]
                vnext["address"] = "197.221.237.248"
                user = vnext["users"][0]
                stream = proxy["streamSettings"]
                
                tls = stream.get("tlsSettings", {})
                net = stream.get("network", "ws")
                
                path = "/"
                host = ""
                if net == "xhttp":
                    xh = stream.get("xhttpSettings", {})
                    path = xh.get("path", "/")
                    host = xh.get("headers", {}).get("Host", tls.get("serverName", ""))
                elif net == "ws":
                    ws = stream.get("wsSettings", {})
                    path = ws.get("path", "/")
                    host = ws.get("headers", {}).get("Host", "")

                params = [f"allowInsecure=1", "encryption=none", f"fp={tls.get('fingerprint', 'chrome')}", 
                          f"host={host}", "mode=stream-one" if net == "xhttp" else None, 
                          f"path={path}", f"security={stream.get('security', 'none')}", 
                          f"sni={tls.get('serverName', '')}", f"type={net}"]
                
                params = [p for p in params if p is not None]
                links.append(f"vless://{user['id']}@{vnext['address']}:{vnext['port']}?{'&'.join(params)}#{prefix}-{conf.get('remarks', 'server')}")
            except Exception:
                continue

        return links
    except Exception as e:
        print(f"Ошибка обработки: {e}")
        return []

if __name__ == "__main__":
    all_links = ""
    for target in TARGETS:
        for link in get_vless_links(target):
            all_links += link + "\n\n"

    if all_links and GITHUB_TOKEN:
        update_gist(all_links)
    else:
        print("Ссылки не найдены или отсутствует токен.")
